    counts=collections.Counter(); times=[]; tokens=collections.Counter(); token_events=[]
    with p.open(encoding='utf-8') as f:
      for line in f:
        try: o=json.loads(line)
        except: continue
        counts[o.get('type','<none>')]+=1
        if o.get('timestamp'): times.append(o['timestamp'])
        def walk(x):
          if isinstance(x,dict):
            for k,v in x.items():
              if k in ('inputTokens','outputTokens','cacheReadTokens','cacheWriteTokens') and isinstance(v,(int,float)):
                tokens[k]+=v
              walk(v)
          elif isinstance(x,list):
            for v in x: walk(v)
        walk(o)
    print(p.name)
    print('events',dict(counts))
    print('range',min(times) if times else None,max(times) if times else None)
    print('tokens',dict(tokens))
