for p in sorted(root.glob('phase*-task-*.jsonl')):
 totals={}
 def walk(x,path=''):
  if isinstance(x,dict):
   for k,v in x.items():
    q=f'{path}.{k}' if path else k
    if re.search(r'(token|premium|aiu)',k,re.I) and isinstance(v,(int,float,str,bool)):
     totals[q]=v
    walk(v,q)
  elif isinstance(x,list):
   for i,v in enumerate(x): walk(v,f'{path}[{i}]')
 for line in p.open(encoding='utf-8'):
  o=json.loads(line)
  if o.get('type') in ('session.usage_checkpoint','result'): walk(o)
 print(p.name)
 for k,v in totals.items(): print(f'{k}={v}')
